import { defineConfig } from 'orval';

// Generates typed fetch functions and TanStack Query hooks from the backend contract.
// Run `npm run api:generate` after updating ../api/openapi.json; never edit src/api/generated by hand.
// Every call goes through `apiFetch`, which attaches the access token and renews it when it expires.
export default defineConfig({
  cooperar: {
    input: { target: '../api/openapi.json' },
    output: {
      mode: 'tags-split',
      target: 'src/api/generated',
      schemas: 'src/api/generated/model',
      client: 'react-query',
      httpClient: 'fetch',
      clean: true,
      override: {
        mutator: { path: 'src/api/apiFetch.ts', name: 'apiFetch' },
      },
    },
  },
});
